(function(){"use strict";const a="https://weather-grab.nabholz.workers.dev/?lat=",o="https://background-grab.nabholz.workers.dev/?cat=";chrome.runtime.onMessage.addListener((r,h,t)=>(r.message=="fetch-weather"&&fetch(a+r.latitude+"&lon="+r.longitude).then(e=>e.json()).then(e=>{t({response:e})}).catch(e=>{console.error(e),t({error:"Failed to fetch weather data"})}),r.message=="fetch-background"&&fetch(o+r.query).then(e=>e.json()).then(e=>{t({response:e})}).catch(e=>{console.error(e),t({error:"Failed to fetch background data"})}),!0))})();
